package com.autocare.platform.order;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import com.autocare.platform.gateway.identity.OperatorIdentity;
import static org.junit.jupiter.api.Assertions.*;
class JdbcPriceComparisonsTest extends JdbcPricePoliciesTest {
 PriceComparisons comparisons;
 @BeforeEach void comparisons(){comparisons=new PriceComparisons(db,policies,new OperatorIdentity(jdbc,null,new DataSourceTransactionManager(jdbc.getDataSource())));}
 com.fasterxml.jackson.databind.JsonNode result(){return json.valueToTree(comparisons.detail(operator,1)).path("comparison");}
 long range(String lower,String upper){var b=config().put("lower_price",lower).put("upper_price",upper);long id=policies.create(operator,key(),b).path("data").path("id").asLong();activate(id);clock.value=ReservationStore.instant(policies.row(id,false).get("valid_from"));return id;}
 void reason(String expected){var r=result();assertEquals("UNKNOWN",r.path("state").asText());assertEquals(expected,r.path("reason").asText());assertFalse(r.path("review_required").asBoolean());}
 @Test void exactInclusiveEndpointsAndOneCentOutsideAreDistinctWithoutPriceWrites(){for(String[] bounds:List.of(new String[]{"12.34","12.34","WITHIN_RANGE"},new String[]{"12.34","12.35","WITHIN_RANGE"},new String[]{"12.33","12.34","WITHIN_RANGE"},new String[]{"12.35","20.00","BELOW_RANGE"},new String[]{"10.00","12.33","ABOVE_RANGE"})){long id=range(bounds[0],bounds[1]);var n=result();assertEquals(bounds[2],n.path("state").asText());assertEquals("VERIFIED",n.path("reason").asText());assertEquals(!bounds[2].equals("WITHIN_RANGE"),n.path("review_required").asBoolean());assertEquals("12.34",n.path("current").path("source").path("price").asText());policies.status(operator,id,key(),statusBody(2,"STOPPED"));}assertEquals(new java.math.BigDecimal("12.34"),jdbc.queryForObject("SELECT price FROM merchant_project WHERE id=1",java.math.BigDecimal.class));}
 @Test void sourceMissingDraftStoppedAndExpiredNeverFallBackToReferenceRange(){reason("POLICY_MISSING");long id=policy();reason("POLICY_NOT_PUBLISHED");activate(id);reason("NOT_STARTED");clock.value=ReservationStore.instant(policies.row(id,false).get("valid_from"));assertEquals("WITHIN_RANGE",result().path("state").asText());clock.value=ReservationStore.instant(policies.row(id,false).get("valid_to"));reason("EXPIRED");policies.status(operator,id,key(),statusBody(2,"STOPPED"));reason("POLICY_STOPPED");}
 @Test void currentVersionProjectRegionAndAuditChangesRequireNewConfirmation(){range("10.00","15.00");saveQuote();reason("SOURCE_CHANGED");jdbc.update("DELETE FROM merchant_project_version WHERE version=2");reason("SOURCE_UNKNOWN");}
 @Test void projectContentOrRegionChangesAndFrozenSourceAreNotSilentlyRebound(){long id=range("10.00","15.00");String frozen=db.json(policies.detail(operator,id));jdbc.update("UPDATE standard_project SET service_content='different service' WHERE id=1");reason("SOURCE_CHANGED");jdbc.update("UPDATE standard_project SET service_content='synthetic service' WHERE id=1");jdbc.update("UPDATE merchant SET region_code='440105' WHERE id=1");reason("SOURCE_CHANGED");assertEquals(frozen,db.json(policies.detail(operator,id)));}
 @Test void unavailablePublishedQuotesRemainVisibleUntilExplicitlyStopped(){long id=range("10.00","15.00");jdbc.update("UPDATE merchant_project SET on_shelf=0 WHERE id=1");reason("SOURCE_UNAVAILABLE");var list=json.valueToTree(comparisons.list(operator,1));assertEquals(1,list.path("comparisons").path("total").asInt());assertTrue(result().path("current").isNull());assertEquals(id,result().path("policy").path("id").asLong());policies.status(operator,id,key(),statusBody(2,"STOPPED"));assertEquals(0,((Map<?,?>)comparisons.list(operator,1).get("comparisons")).get("total") instanceof Number n?n.intValue():-1);assertEquals(404,code(()->comparisons.detail(operator,1)));}
 @Test void publicationProofAndFrozenRangeTamperingFailClosed(){long id=range("10.00","15.00");jdbc.update("UPDATE audit_log SET after_state=JSON_SET(after_state,'$.comparison_available',false) WHERE action='PRICE_POLICY_STATUS'");assertEquals("WITHIN_RANGE",result().path("state").asText());jdbc.update("UPDATE price_monitor_policy SET upper_price=20 WHERE id=?",id);reason("POLICY_SOURCE_UNKNOWN");jdbc.update("UPDATE price_monitor_policy SET upper_price=15 WHERE id=?",id);jdbc.update("DELETE FROM audit_log WHERE action='PRICE_POLICY_STATUS'");reason("POLICY_SOURCE_UNKNOWN");}
 @Test void stoppedPolicyCannotRegainValidityByRestoringAnOldPublishedRow(){long id=range("10.00","15.00");policies.status(operator,id,key(),statusBody(2,"STOPPED"));jdbc.update("UPDATE price_monitor_policy SET status='PUBLISHED',revision=2,stopped_at=NULL WHERE id=?",id);reason("POLICY_SOURCE_UNKNOWN");jdbc.update("UPDATE audit_log SET is_deleted=1 WHERE action='PRICE_POLICY_STATUS' AND JSON_UNQUOTE(JSON_EXTRACT(after_state,'$.status'))='STOPPED'");reason("POLICY_SOURCE_UNKNOWN");}
 @Test void softDeletedPublicationAndQuotationEvidenceAreUnknown(){range("10.00","15.00");jdbc.update("UPDATE audit_log SET is_deleted=1 WHERE action='PRICE_POLICY_STATUS'");reason("POLICY_SOURCE_UNKNOWN");jdbc.update("UPDATE audit_log SET is_deleted=0 WHERE action='PRICE_POLICY_STATUS'");assertEquals("WITHIN_RANGE",result().path("state").asText());jdbc.update("UPDATE audit_log SET is_deleted=1 WHERE action='MERCHANT_PROJECT_SAVE'");reason("SOURCE_UNKNOWN");}
 @Test void invalidStoredPolicyAndOriginalQuoteProofProduceUnknownNotFakeNormal(){long id=range("10.00","15.00");jdbc.update("UPDATE price_monitor_policy SET rule_version='UNKNOWN' WHERE id=?",id);reason("POLICY_SOURCE_UNKNOWN");assertTrue(result().path("policy").isNull());jdbc.update("UPDATE price_monitor_policy SET rule_version='R8B_PRICE_SOURCE_V1' WHERE id=?",id);jdbc.update("DELETE FROM audit_log WHERE action='MERCHANT_PROJECT_SAVE'");reason("SOURCE_UNKNOWN");}
 @Test void onlyIndependentCurrentPermissionAllowsReadAndNoReadHasSideEffects(){range("10.00","15.00");int audit=count("audit_log"),writes=count("idempotency_record"),policiesBefore=count("price_monitor_policy"),versions=count("merchant_project_version");comparisons.list(operator,1);comparisons.detail(operator,1);assertEquals(audit,count("audit_log"));assertEquals(writes,count("idempotency_record"));assertEquals(policiesBefore,count("price_monitor_policy"));assertEquals(versions,count("merchant_project_version"));jdbc.update("UPDATE operator_account SET can_price_monitor=0,can_catalog=1,can_analytics=1 WHERE id=1");assertEquals(403,code(()->comparisons.list(operator,1)));assertEquals(403,code(()->comparisons.detail(operator,1)));jdbc.update("UPDATE operator_account SET can_price_monitor=1 WHERE id=1");jdbc.update("UPDATE auth_session SET revoked_at=UTC_TIMESTAMP() WHERE id=?",operator.session());assertEquals(401,code(()->comparisons.detail(operator,1)));}
 @Test void paginationAndObservedAtBindToOneReadAndNoPrivateEvidenceLeavesServer(){for(int i=100;i<122;i++){jdbc.update("INSERT INTO standard_project(id,category,project_name,service_content,base_price_low,base_price_high,status) VALUES(?,1,?,'synthetic',10,20,1)",i,"synthetic-"+i);jdbc.update("INSERT INTO merchant_project(id,merchant_id,project_id,price,on_shelf) VALUES(?,1,?,10,1)",i,i); }var n=json.valueToTree(comparisons.list(operator,1));assertEquals(clock.value.toString(),n.path("observed_at").asText());assertEquals(23,n.path("comparisons").path("total").asInt());assertEquals(20,n.path("comparisons").path("items").size());assertEquals(3,json.valueToTree(comparisons.list(operator,2)).path("comparisons").path("items").size());assertEquals(400,code(()->comparisons.list(operator,0)));assertEquals(404,code(()->comparisons.detail(operator,999)));for(String k:List.of("actor_staff_id","submission_key","audit_id","phone","after_state"))assertFalse(n.toString().contains("\""+k+"\""));}
 @Test void maximumPriceComparisonUsesDecimalCentsExactly(){quotes.save(merchant,key(),new com.autocare.platform.service.QuoteInput(1,new java.math.BigDecimal("99999999.99"),1));range("99999999.98","99999999.99");assertEquals("WITHIN_RANGE",result().path("state").asText());}
}
